+static int it6625_read_byte(struct it6625 *it6625, u8 reg)
+{
+	unsigned int val;
+	int err;
+	struct device *dev = it6625->dev;
+
+	err = regmap_read(it6625->it6625_regmap, reg, &val);
+	if (err < 0) {
+		dev_err(dev, "reg[0x%x] read failed err: %d", reg, err);
+		return err;
+	}
+
+	return val;
+}
