+{
+	int err;
+	struct device *dev = it6625->dev;
+
+	err = regmap_write(it6625->it6625_regmap, reg, val);
+	if (err < 0) {
+		dev_err(dev, "reg[0x%x] write failed err: %d", reg, err);
+		return err;
+	}
+
+	return 0;
+}
