 static bool use_cmb_sqes = true;
 module_param(use_cmb_sqes, bool, 0444);
@@ -377,6 +506,7 @@ struct nvme_queue {
 	u16 cq_vector;
 	u16 sq_tail;
 	u16 last_sq_tail;
+	u16 sq_head;
